    19	function card(u){const available=u.status==='AVAILABLE';return `<article class="card" data-category="${u.category}"><div class="row between"><span class="tag">${u.asset_tag}</span>${status(u.status)}</div><h3>${u.model}</h3><div class="muted">${u.category} · ${u.location_name}</div><div class="meta"><div><div class="price">${money(u.daily_rate_cents)} <small>/ day</small></div></div><div>Deposit<br><b>${money(u.deposit_cents)}</b></div></div><div class="muted">Replacement ${money(u.replacement_value_cents)}${u.required_certification?` · Requires ${u.required_certification}`:''}</div>${available?`<button class="btn dark" data-book="${u.id}">View dates & book</button>`:'<button class="btn ghost" disabled>Not available for walk-up</button>'}</article>`}
    20	function renderCatalog(){const cats=['All',...new Set(state.units.map(u=>u.category))];const list=state.filter==='All'?state.units:state.units.filter(u=>u.category===state.filter);$('#content').innerHTML=`<div class="section" id="catalog"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">THE EQUIPMENT WALL</p><h2>Choose your kit</h2><p>Every card is one physical, serialized unit.</p></div><div class="filters">${cats.map(c=>`<button class="${c===state.filter?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div></div><div class="grid">${list.map(card).join('')}</div></div>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderCatalog()});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>book(state.units.find(u=>u.id===b.dataset.book)))}
    21	function book(u){const today=new Date();today.setDate(today.getDate()+1);const start=today.toISOString().slice(0,10);today.setDate(today.getDate()+2);const end=today.toISOString().slice(0,10);$('#dialogBody').innerHTML=`<p class="tag">${u.asset_tag} · ${u.location_name}</p><h2>${u.model}</h2><p class="muted">${money(u.daily_rate_cents)} per day · ${money(u.deposit_cents)} refundable deposit</p><form id="bookForm" class="stack"><div class="row"><div class="field"><label>Start day</label><input name="start_date" type="date" value="${start}" required></div><div class="field"><label>Return day</label><input name="end_date" type="date" value="${end}" required></div></div><button class="btn dark" type="submit">Get live price</button></form><div id="quote"></div>`;$('#dialog').showModal();$('#bookForm').onsubmit=async e=>{e.preventDefault();const body={unit_id:u.id,...Object.fromEntries(new FormData(e.target))};try{const d=await api('/api/quotes',{method:'POST',body:JSON.stringify(body)});const q=d.quote;$('#quote').innerHTML=`<div class="panel"><div class="row between"><b>${q.day_count} calendar day${q.day_count>1?'s':''}</b><span class="total">${money(q.total_cents)}</span></div><div class="breakdown"><div><span>Kit hire</span><b>${money(q.rental_cents)}</b></div>${q.discount_cents?`<div><span>7+ day saving</span><b>−${money(q.discount_cents)}</b></div>`:''}<div><span>Weekend line</span><b>${money(q.weekend_cents)}</b></div><div><span>County tax</span><b>${money(q.tax_cents)}</b></div><div><span>Hull insurance</span><b>${money(q.hull_cents)}</b></div><div><span>Refundable deposit</span><b>${money(q.deposit_cents)}</b></div></div><button class="btn" id="pay">Continue to secure Stripe Checkout</button><p class="muted">Dates are held only after Stripe confirms payment.</p></div>`;$('#pay').onclick=async()=>{try{const x=await api('/api/checkout',{method:'POST',body:JSON.stringify(body)});location.href=x.checkout_url}catch(err){flash(err.message,true)}}}catch(err){$('#quote').innerHTML=`<div class="role-banner">${err.message}</div>`}}}
