a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='GearVault-hire.ics';a.click()});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(confirm('Cancel this paid rental before pickup?'))try{const x=await api(`/api/reservations/${b.dataset.cancel}/cancel`,{method:'POST',body:'{}'});flash(x.message);showRecords();await load()}catch(e){flash(e.message,true)}})}catch(e){flash(e.message,true)}}
